saveCandidatePool:
function saveCandidatePool(pool) {
  try {
    const cutoff = Date.now() - CANDIDATE_POOL_MAX_AGE_MS;
    const cleaned = pool
      .filter(item => item?.track?.id && Number(item.savedAt || 0) >= cutoff)
      .sort((a, b) => Number(b.savedAt || 0) - Number(a.savedAt || 0))
      .slice(0, CANDIDATE_POOL_MAX_ITEMS);
    localStorage.setItem(CANDIDATE_POOL_KEY, JSON.stringify(cleaned));
  } catch (err) {
    console.warn("Nie udało się zapisać lokalnej puli kandydatów.", err);
  }
}
